parameters.jsCode:
// Turn a load-test CSV into statistics, and decide Pass or Fail.
//
// Two rules drive everything here:
//
//   1. The model never sees a row. A single request taking 4 seconds means
//      nothing; the 95th percentile taking 4 seconds is the whole story. Only
//      the statistics computed here are ever sent.
//   2. The verdict is arithmetic, so it is computed here rather than asked for.
//      This report goes to people who cannot check it.
//
// Percentiles come from a single-pass histogram rather than sorting. A one hour
// run at 200 rps is ~720,000 rows; sorting that in a Code node is slow and
// memory-hungry, while a histogram is one pass and constant memory.

const FINE_MAX = 10000;   // 1ms buckets below 10s
const COARSE_MS = 50;     // 50ms buckets from 10s
const COARSE_MAX = 60000; // then a single overflow bucket
const MAX_LABELS = 50;

const hook = $('Perf Test Webhook').first().json;
const body = (hook && hook.body) || hook || {};

// ---------------------------------------------------------------- input ----
// Three ways in, because a 100MB .jtl cannot travel in a webhook body but a
// sample can, and a tester with a file in their hand should not need a URL.
let csv = '';
let source = 'none';
if (typeof body.csv_text === 'string' && body.csv_text.trim()) {
  csv = body.csv_text;
  source = 'inline';
} else {
  let fetched = null;
  try { fetched = $input.first(); } catch (e) { fetched = null; }
  const bin = fetched && fetched.binary;
  const binKey = bin && Object.keys(bin)[0];
  if (binKey && bin[binKey].data) {
    csv = Buffer.from(bin[binKey].data, 'base64').toString('utf8');
    source = 'file';
  } else if (fetched && fetched.json) {
    const j = fetched.json;
    const text = typeof j === 'string' ? j : (j.data || j.body || j.csv || '');
    if (typeof text === 'string' && text.includes(',')) { csv = text; source = 'url'; }
  }
}

// ------------------------------------------------------------ slo config ----
const slo = Object.assign(
  { p95_ms: 2000, p99_ms: 5000, error_rate_pct: 1.0, min_throughput_rps: null },
  body.slo || {}
);
const testName = String(body.test_name || 'Load test').trim();

// --------------------------------------------------------------- parsing ----
// Hand-rolled because JMeter's failureMessage regularly contains commas and
// quotes, and splitting on "," corrupts every row after the first bad one.
function splitCsvLine(line) {
  const out = [];
  let cur = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quoted) {
      if (c === '"') {
        if (line[i + 1] === '"') { cur += '"'; i++; } else { quoted = false; }
      } else cur += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') { out.push(cur); cur = ''; }
    else cur += c;
  }
  out.push(cur);
  return out;
}

const lines = csv.split(/\r?\n/);
let headerIdx = lines.findIndex((l) => l.trim() !== '');
const header = headerIdx === -1 ? [] : splitCsvLine(lines[headerIdx]).map((h) => h.trim());
const col = {};
header.forEach((h, i) => { col[h] = i; });

// Detect the tool from the header rather than being told which it is.
let format = 'unknown';
if (col.elapsed !== undefined && col.timeStamp !== undefined) format = 'jmeter';
else if (col.metric_name !== undefined && col.metric_value !== undefined) format = 'k6';

// -------------------------------------------------------------- counters ----
const fine = new Int32Array(FINE_MAX);
const coarse = new Int32Array(Math.ceil((COARSE_MAX - FINE_MAX) / COARSE_MS) + 1);
let over = 0;
let total = 0, failed = 0, sum = 0, min = Infinity, max = 0;
let tsMin = Infinity, tsMax = -Infinity;
const labels = new Map();
const codes = new Map();

function record(ms) {
  if (ms < FINE_MAX) fine[Math.max(0, ms)]++;
  else if (ms < COARSE_MAX) coarse[Math.floor((ms - FINE_MAX) / COARSE_MS)]++;
  else over++;
}

function labelBucket(name) {
  if (!labels.has(name)) {
    if (labels.size >= MAX_LABELS) name = '(other)';
    if (!labels.has(name)) labels.set(name, { count: 0, errors: 0, sum: 0, max: 0, lat: [] });
  }
  return labels.get(name);
}

for (let i = headerIdx + 1; i < lines.length; i++) {
  const raw = lines[i];
  if (!raw || !raw.trim()) continue;
  const f = splitCsvLine(raw);

  let ms = NaN, ok = true, label = 'unknown', ts = NaN, code = '';

  if (format === 'jmeter') {
    ms = Number(f[col.elapsed]);
    ok = String(f[col.success]).toLowerCase() !== 'false';
    label = f[col.label] || 'unknown';
    ts = Number(f[col.timeStamp]);
    code = String(f[col.responseCode] || '').trim();
  } else if (format === 'k6') {
    // k6 emits one row per metric sample, so only the duration rows are
    // requests. Everything else (vus, iterations, data_sent) is noise here.
    if (String(f[col.metric_name]).trim() !== 'http_req_duration') continue;
    ms = Number(f[col.metric_value]);
    const expected = String(f[col.expected_response] || '').toLowerCase();
    const status = Number(f[col.status]);
    ok = expected === 'false' ? false : !(status >= 400);
    label = f[col.name] || f[col.url] || 'unknown';
    ts = Number(f[col.timestamp]) * 1000; // k6 timestamps are seconds
    code = String(f[col.status] || '').trim();
  } else {
    continue;
  }

  if (!Number.isFinite(ms) || ms < 0) continue;

  total++;
  sum += ms;
  if (ms < min) min = ms;
  if (ms > max) max = ms;
  record(Math.round(ms));
  if (Number.isFinite(ts)) { if (ts < tsMin) tsMin = ts; if (ts > tsMax) tsMax = ts; }
  if (!ok) {
    failed++;
    const key = code || 'unknown';
    codes.set(key, (codes.get(key) || 0) + 1);
  }

  const b = labelBucket(label);
  b.count++;
  b.sum += ms;
  if (ms > b.max) b.max = ms;
  if (!ok) b.errors++;
  if (b.lat.length < 20000) b.lat.push(ms); // enough for a per-label p95
}

// ----------------------------------------------------------- percentiles ----
function percentile(p) {
  if (!total) return 0;
  const target = Math.ceil((p / 100) * total);
  let seen = 0;
  for (let i = 0; i < FINE_MAX; i++) {
    seen += fine[i];
    if (seen >= target) return i;
  }
  for (let i = 0; i < coarse.length; i++) {
    seen += coarse[i];
    if (seen >= target) return FINE_MAX + i * COARSE_MS + COARSE_MS / 2;
  }
  return COARSE_MAX;
}

function labelP95(arr) {
  if (!arr.length) return 0;
  const s = arr.slice().sort((a, b) => a - b);
  return Math.round(s[Math.min(s.length - 1, Math.ceil(0.95 * s.length) - 1)]);
}

const round1 = (n) => Math.round(n * 10) / 10;
const errorRate = total ? round1((failed / total) * 100) : 0;
const durationSec = (Number.isFinite(tsMin) && Number.isFinite(tsMax) && tsMax > tsMin)
  ? (tsMax - tsMin) / 1000 : 0;
const throughput = durationSec ? round1(total / durationSec) : 0;

const p50 = percentile(50), p90 = percentile(90), p95 = percentile(95), p99 = percentile(99);

const perEndpoint = Array.from(labels.entries())
  .map(([name, v]) => ({
    label: name,
    count: v.count,
    error_rate: v.count ? round1((v.errors / v.count) * 100) : 0,
    p95_ms: labelP95(v.lat),
    mean_ms: v.count ? Math.round(v.sum / v.count) : 0,
    max_ms: Math.round(v.max),
  }))
  .sort((a, b) => b.p95_ms - a.p95_ms);

const errorBreakdown = Array.from(codes.entries())
  .map(([code, count]) => ({ code, count }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 10);

// ---------------------------------------------------------- the verdict ----
// Arithmetic, not judgement. WARN exists because a run that squeaks through at
// 1,950ms against a 2,000ms SLO is not a clean pass, and saying so is the
// difference between a report and a rubber stamp.
const breaches = [];
const warnings = [];
const WARN_BAND = 0.9;

function judge(name, actual, threshold, unit) {
  if (threshold === null || threshold === undefined) return;
  if (actual > threshold) {
    breaches.push({
      slo: name, threshold, actual, unit,
      over_by_pct: threshold ? Math.round(((actual - threshold) / threshold) * 100) : 0,
    });
  } else if (actual >= threshold * WARN_BAND) {
    warnings.push({ slo: name, threshold, actual, unit });
  }
}

judge('p95 response time', p95, slo.p95_ms, 'ms');
judge('p99 response time', p99, slo.p99_ms, 'ms');
judge('error rate', errorRate, slo.error_rate_pct, '%');
if (slo.min_throughput_rps) {
  if (throughput < slo.min_throughput_rps) {
    breaches.push({
      slo: 'throughput', threshold: slo.min_throughput_rps, actual: throughput, unit: 'rps',
      over_by_pct: -Math.round(((slo.min_throughput_rps - throughput) / slo.min_throughput_rps) * 100),
    });
  }
}

let verdict;
if (format === 'unknown' || total === 0) verdict = 'NO DATA';
else if (breaches.length) verdict = 'FAIL';
else if (warnings.length) verdict = 'WARN';
else verdict = 'PASS';

return [{
  json: {
    test_name: testName,
    source,
    format,
    verdict,
    total_requests: total,
    failed_requests: failed,
    error_rate: errorRate,
    p50_ms: p50, p90_ms: p90, p95_ms: p95, p99_ms: p99,
    min_ms: total ? Math.round(min) : 0,
    max_ms: Math.round(max),
    mean_ms: total ? Math.round(sum / total) : 0,
    throughput_rps: throughput,
    duration_seconds: Math.round(durationSec),
    started_at: Number.isFinite(tsMin) ? new Date(tsMin).toISOString() : '',
    ended_at: Number.isFinite(tsMax) ? new Date(tsMax).toISOString() : '',
    slo,
    breaches,
    warnings,
    per_endpoint: perEndpoint.slice(0, 15),
    endpoint_count: perEndpoint.length,
    error_breakdown: errorBreakdown,
    requests_over_60s: over,
    no_data: total === 0,
  },
}];

parameters.text:
=PERFORMANCE RUN: {{ $json.test_name }}
Source format: {{ $json.format }}

VERDICT (already decided by comparing measurements against agreed thresholds - do not argue with it):
  {{ $json.verdict }}

MEASURED - these are the only figures you may use:
  Requests: {{ $json.total_requests }}   Failed: {{ $json.failed_requests }}   Error rate: {{ $json.error_rate }}%
  Response times (ms): p50 {{ $json.p50_ms }}, p90 {{ $json.p90_ms }}, p95 {{ $json.p95_ms }}, p99 {{ $json.p99_ms }}
  Mean {{ $json.mean_ms }}ms, slowest {{ $json.max_ms }}ms
  Throughput: {{ $json.throughput_rps }} requests/second over {{ $json.duration_seconds }} seconds

AGREED THRESHOLDS:
  p95 {{ $json.slo.p95_ms }}ms, p99 {{ $json.slo.p99_ms }}ms, error rate {{ $json.slo.error_rate_pct }}%

BREACHED:
{{ JSON.stringify($json.breaches, null, 1) }}

CLOSE TO THE LIMIT (within 10%):
{{ JSON.stringify($json.warnings, null, 1) }}

PER ENDPOINT (slowest first):
{{ JSON.stringify($json.per_endpoint, null, 1) }}

ERRORS BY RESPONSE CODE:
{{ JSON.stringify($json.error_breakdown, null, 1) }}

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "headline",
    "business_impact",
    "risk_level",
    "key_findings",
    "worst_offender_note",
    "recommended_actions",
    "caveats"
  ],
  "properties": {
    "headline": {
      "type": "string",
      "description": "One sentence. A reader who sees only this line should know whether to worry."
    },
    "business_impact": {
      "type": "string",
      "description": "Two or three sentences on what this means for real users, in plain language."
    },
    "risk_level": {
      "type": "string",
      "enum": [
        "Low",
        "Moderate",
        "High",
        "Critical"
      ]
    },
    "key_findings": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Three to five bullets, each citing a figure supplied in the statistics."
    },
    "worst_offender_note": {
      "type": "string",
      "description": "One or two sentences on the endpoint with the worst p95 and why it stands out."
    },
    "recommended_actions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Two to four concrete next steps, ordered by impact."
    },
    "caveats": {
      "type": "string",
      "description": "What this test does not prove: load shape, duration, environment, representativeness."
    }
  }
}

parameters.jsCode:
// Merge the computed statistics with the model's narrative, and refuse to let
// the narrative contradict them.
//
// This report is read by people who cannot check it, which changes what
// "validation" has to mean. It is not enough for the JSON to be well shaped:
//   - the verdict must be the one arithmetic produced, not the one the model
//     liked;
//   - every figure quoted in the prose must be a figure the parser actually
//     computed;
//   - an empty test must never read as a passing one.

const stats = $('Parse CSV Stats').first().json;
const incoming = $input.first().json;
const model = (incoming && incoming.output) || incoming || {};

const RISKS = ['Low', 'Moderate', 'High', 'Critical', 'Unknown'];
const notes = [];

const str = (v, fallback) => {
  if (v === undefined || v === null) return fallback;
  const s = String(v).trim();
  return s === '' ? fallback : s;
};
const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean) : []);
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// --- guard rail 1: the verdict is not the model's to give -------------------
const verdict = stats.verdict;
let risk = RISKS.includes(str(model.risk_level, '')) ? str(model.risk_level, '') : 'Unknown';

if (verdict === 'NO DATA') {
  risk = 'Unknown';
  notes.push('No parseable requests were found, so no verdict was possible');
} else if (verdict === 'FAIL' && (risk === 'Low' || risk === 'Unknown')) {
  // A breached SLO is not low risk, whatever the prose says.
  risk = 'High';
  notes.push('Verdict is FAIL, so risk was raised to High');
} else if (verdict === 'PASS' && risk === 'Critical') {
  risk = 'Moderate';
  notes.push('Verdict is PASS with no breaches, so Critical risk was lowered');
}

// --- guard rail 2: no figure may appear that the parser did not produce ------
// Build the set of numbers that legitimately exist, then read every number out
// of the model's prose and flag the ones that do not.
const allowed = new Set();
const allow = (n) => {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return;
  const v = Number(n);
  allowed.add(v);
  allowed.add(Math.round(v));
  allowed.add(Math.round(v * 10) / 10);
  if (v >= 1000) allowed.add(Math.round(v / 1000 * 10) / 10); // "4.2 seconds" for 4210ms
};
[
  stats.total_requests, stats.failed_requests, stats.error_rate, stats.p50_ms, stats.p90_ms,
  stats.p95_ms, stats.p99_ms, stats.min_ms, stats.max_ms, stats.mean_ms, stats.throughput_rps,
  stats.duration_seconds, stats.endpoint_count, stats.requests_over_60s,
  stats.slo && stats.slo.p95_ms, stats.slo && stats.slo.p99_ms,
  stats.slo && stats.slo.error_rate_pct, stats.slo && stats.slo.min_throughput_rps,
].forEach(allow);
(stats.per_endpoint || []).forEach((e) => { allow(e.count); allow(e.p95_ms); allow(e.error_rate); allow(e.mean_ms); allow(e.max_ms); });
(stats.error_breakdown || []).forEach((e) => { allow(e.count); allow(Number(e.code)); });
(stats.breaches || []).forEach((b) => { allow(b.threshold); allow(b.actual); allow(Math.abs(b.over_by_pct)); });

const prose = [
  str(model.headline, ''), str(model.business_impact, ''), str(model.worst_offender_note, ''),
  str(model.caveats, ''), arr(model.key_findings).join(' '), arr(model.recommended_actions).join(' '),
].join(' ');

const unverified = [];
// Only check figures big enough to be claims. Small integers are ordinals and
// list counts far more often than they are invented statistics.
for (const m of prose.matchAll(/\b\d[\d,]*(?:\.\d+)?\b/g)) {
  const n = Number(m[0].replace(/,/g, ''));
  if (!Number.isFinite(n) || n < 10) continue;
  let ok = false;
  for (const a of allowed) {
    if (a === 0) { if (n === 0) { ok = true; break; } continue; }
    if (Math.abs(n - a) / Math.abs(a) <= 0.01) { ok = true; break; }
  }
  if (!ok && !unverified.includes(m[0])) unverified.push(m[0]);
}
if (unverified.length) {
  notes.push('figures not produced by the parser appear in the narrative: ' + unverified.join(', '));
}

// --- assemble ---------------------------------------------------------------
const headline = verdict === 'NO DATA'
  ? 'No usable data was found in the supplied report'
  : str(model.headline, 'Performance run completed');

const report = {
  test_name: stats.test_name,
  verdict,
  risk_level: risk,
  headline,
  business_impact: verdict === 'NO DATA'
    ? 'The file contained no rows this analyser could read, so nothing can be said about performance. This is not a pass.'
    : str(model.business_impact, 'Not Provided'),
  key_findings: arr(model.key_findings).slice(0, 6),
  worst_offender_note: str(model.worst_offender_note, 'Not Provided'),
  recommended_actions: arr(model.recommended_actions).slice(0, 6),
  caveats: str(model.caveats, 'Not Provided'),

  // every number below comes from the parser, never the model
  total_requests: stats.total_requests,
  failed_requests: stats.failed_requests,
  error_rate: stats.error_rate,
  p50_ms: stats.p50_ms, p90_ms: stats.p90_ms, p95_ms: stats.p95_ms, p99_ms: stats.p99_ms,
  mean_ms: stats.mean_ms, max_ms: stats.max_ms,
  throughput_rps: stats.throughput_rps,
  duration_seconds: stats.duration_seconds,
  format: stats.format,
  slo: stats.slo,
  breaches: stats.breaches,
  warnings: stats.warnings,
  per_endpoint: stats.per_endpoint,
  error_breakdown: stats.error_breakdown,
  figures_unverified: unverified.length > 0,
  validation_notes: notes.length ? notes : ['No corrections were needed'],
};

// --- fragments for the HTML node --------------------------------------------
// The HTML node interpolates expressions but cannot loop, so the repeating
// parts are rendered here.
const VERDICT_COLOUR = { PASS: '#0f7a52', WARN: '#96620a', FAIL: '#b02a20', 'NO DATA': '#55607a' };

report.verdict_colour = VERDICT_COLOUR[verdict] || '#55607a';

report.findings_html = report.key_findings.length
  ? report.key_findings.map((f) => '<li>' + esc(f) + '</li>').join('')
  : '<li>Not Provided</li>';

report.actions_html = report.recommended_actions.length
  ? report.recommended_actions.map((a) => '<li>' + esc(a) + '</li>').join('')
  : '<li>Not Provided</li>';

report.breaches_html = (report.breaches || []).length
  ? report.breaches.map((b) =>
      '<tr><td>' + esc(b.slo) + '</td><td class="num">' + esc(b.threshold) + esc(b.unit) +
      '</td><td class="num bad">' + esc(b.actual) + esc(b.unit) + '</td><td class="num bad">+' +
      esc(b.over_by_pct) + '%</td></tr>').join('')
  : '<tr><td colspan="4">No thresholds were breached.</td></tr>';

report.endpoints_html = (report.per_endpoint || []).length
  ? report.per_endpoint.map((e) =>
      '<tr><td>' + esc(e.label) + '</td><td class="num">' + esc(e.count) +
      '</td><td class="num">' + esc(e.p95_ms) + 'ms</td><td class="num' +
      (e.error_rate > 0 ? ' bad' : '') + '">' + esc(e.error_rate) + '%</td></tr>').join('')
  : '<tr><td colspan="4">No endpoint breakdown available.</td></tr>';

// --- Telegram body ----------------------------------------------------------
const mark = { PASS: 'PASS', WARN: 'WARN', FAIL: 'FAIL', 'NO DATA': 'NO DATA' }[verdict];
report.telegram_text = [
  mark + ' - ' + report.test_name,
  '',
  report.headline,
  '',
  'Requests: ' + report.total_requests + '   Errors: ' + report.failed_requests + ' (' + report.error_rate + '%)',
  'p95: ' + report.p95_ms + 'ms   p99: ' + report.p99_ms + 'ms   throughput: ' + report.throughput_rps + '/s',
  'SLO: p95 ' + report.slo.p95_ms + 'ms, p99 ' + report.slo.p99_ms + 'ms, errors ' + report.slo.error_rate_pct + '%',
  '',
  (report.breaches || []).length
    ? 'Breached: ' + report.breaches.map((b) => b.slo + ' ' + b.actual + b.unit + ' vs ' + b.threshold + b.unit).join('; ')
    : 'No thresholds breached.',
  '',
  'Impact: ' + report.business_impact,
  '',
  'Actions:',
  report.recommended_actions.length ? report.recommended_actions.map((a, i) => (i + 1) + '. ' + a).join('\n') : 'Not Provided',
  '',
  'Risk: ' + report.risk_level,
].join('\n');

return [{ json: report }];
